ALTER TABLE media ADD COLUMN orientation ENUM('landscape','portrait','any') NOT NULL DEFAULT 'any', ADD COLUMN layout_type ENUM('fullscreen','bottom','side','half_horizontal','half_vertical') NOT NULL DEFAULT 'fullscreen', ADD COLUMN width_px INT NULL, ADD COLUMN height_px INT NULL;
ALTER TABLE playlists ADD COLUMN layout_type ENUM('fullscreen','bottom','side','half_horizontal','half_vertical') NOT NULL DEFAULT 'fullscreen';
ALTER TABLE devices ADD COLUMN location_label VARCHAR(190) NULL, ADD COLUMN pairing_code_hash CHAR(64) NULL, ADD COLUMN pairing_expires DATETIME NULL, ADD COLUMN device_token_hash CHAR(64) NULL, ADD COLUMN active_playlist_id BIGINT UNSIGNED NULL;
CREATE TABLE IF NOT EXISTS schedule_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL,schedule_id BIGINT UNSIGNED NOT NULL,playlist_id BIGINT UNSIGNED NOT NULL,position INT NOT NULL DEFAULT 0, FOREIGN KEY (schedule_id) REFERENCES schedules(id) ON DELETE CASCADE,FOREIGN KEY (playlist_id) REFERENCES playlists(id),INDEX(tenant_id,schedule_id,position));
INSERT INTO schedule_items(tenant_id,schedule_id,playlist_id,position) SELECT s.tenant_id,s.id,s.playlist_id,0 FROM schedules s WHERE NOT EXISTS (SELECT 1 FROM schedule_items i WHERE i.schedule_id=s.id);
